import math
class V:
    """스칼라 하나와 그 기울기. parents = ((부모 노드, 국소 미분), ...)"""
    def __init__(self, val, parents=()):
        self.val, self.grad, self.parents = val, 0.0, parents
    def __add__(self, o):
        o = o if isinstance(o, V) else V(o)
        return V(self.val + o.val, ((self, 1.0), (o, 1.0)))
    def __mul__(self, o):
        o = o if isinstance(o, V) else V(o)
        return V(self.val * o.val, ((self, o.val), (o, self.val)))
    def sigmoid(self):
        s = 1 / (1 + math.exp(-self.val))
        return V(s, ((self, s * (1 - s)),))
    def backward(self):
        order, seen = [], set()
        def topo(v):                          # 입력 → 출력 순서(위상 정렬)
            if id(v) not in seen:
                seen.add(id(v))
                for p, _ in v.parents: topo(p)
                order.append(v)
        topo(self); self.grad = 1.0
        for v in reversed(order):             # 출력 → 입력, 노드마다 한 번
            for p, local in v.parents:
                p.grad += local * v.grad      # 여러 길로 오면 더한다

x1, x2, x3 = V(1.0), V(2.0), V(3.0)
s = x1 + x2; f = s * x3 + s                   # s 를 두 번 재사용
f.backward()
print(f.val, x1.grad, x2.grad, x3.grad)       # 12.0 4.0 4.0 3.0
